function draw() {
  ctx.clearRect(0, 0, width, height);
  // ship
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.beginPath();
  ctx.moveTo(15, 0);
  ctx.lineTo(-10, -8);
  ctx.lineTo(-10, 8);
  ctx.closePath();
  ctx.fillStyle = ship.shield ? 'cyan' : 'white';
  ctx.fill();
  ctx.restore();
  // asteroids
  ctx.fillStyle = 'gray';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  });
  // UI
  ctx.fillStyle = 'white';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score.value), 10, 20);
  // fuel bar
  ctx.fillStyle = 'lime';
  const fuelW = 100;
  ctx.fillRect(10, 30, fuelW * (ship.fuel / 100), 10);
  ctx.strokeStyle = 'white';
  ctx.strokeRect(10, 30, fuelW, 10);
  // shield indicator
  if (ship.shield) {
    ctx.fillStyle = 'cyan';
    ctx.fillText('Shield', 10, 55);
  }
}

input.newString:
function draw() {
  // background gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#000010');
  bgGrad.addColorStop(1, '#000030');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // starfield
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,255,255,${s.alpha})`;
    ctx.fill();
  });

  // ship shield halo
  if (ship.shield) {
    const halo = ctx.createRadialGradient(ship.x, ship.y, ship.radius, ship.x, ship.y, ship.radius + 20);
    halo.addColorStop(0, 'rgba(0,255,255,0.4)');
    halo.addColorStop(1, 'rgba(0,255,255,0)');
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(ship.x, ship.y, ship.radius + 20, 0, Math.PI * 2);
    ctx.fill();
  }

  // ship
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  // thrust flame
  if (keys['ArrowUp']) {
    ctx.beginPath();
    ctx.moveTo(-12, 0);
    ctx.lineTo(-22, -6);
    ctx.lineTo(-22, 6);
    ctx.closePath();
    ctx.fillStyle = 'orange';
    ctx.fill();
  }
  ctx.beginPath();
  ctx.moveTo(15, 0);
  ctx.lineTo(-10, -8);
  ctx.lineTo(-10, 8);
  ctx.closePath();
  ctx.fillStyle = ship.shield ? 'cyan' : 'white';
  ctx.fill();
  ctx.restore();

  // asteroids (irregular polygon)
  ctx.fillStyle = 'gray';
  asteroids.forEach(a => {
    const points = 8;
    const step = (Math.PI * 2) / points;
    ctx.beginPath();
    for (let i = 0; i < points; i++) {
      const angle = i * step + Math.random() * step * 0.3;
      const r = a.radius * (0.7 + Math.random() * 0.6);
      const x = a.x + Math.cos(angle) * r;
      const y = a.y + Math.sin(angle) * r;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
  });

  // UI
  ctx.fillStyle = 'white';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score.value), 10, 20);
  // fuel bar background
  ctx.fillStyle = 'rgba(255,255,255,0.2)';
  const fuelW = 100;
  ctx.fillRect(10, 30, fuelW, 10);
  // fuel level
  ctx.fillStyle = 'lime';
  ctx.fillRect(10, 30, fuelW * (ship.fuel / 100), 10);
  ctx.strokeStyle = 'white';
  ctx.strokeRect(10, 30, fuelW, 10);
  // shield indicator
  if (ship.shield) {
    ctx.fillStyle = 'cyan';
    ctx.fillText('Shield', 10, 55);
  }
}

